use strict;
use warnings FATAL => 'all';
use PostgreSQL::Test::Cluster;
use PostgreSQL::Test::Utils;
use Test::More;
my $node=PostgreSQL::Test::Cluster->new('function_integration');
$node->init(extra=>['--encoding=UTF8','--locale=C']);
$node->start;
my $s=$node->background_psql('postgres',on_error_stop=>0);
sub sql { $s->query_safe($_[0]); }
sub fails { my($q,$pattern,$label)=@_;my($out,$failed)=$s->query($q);is($failed,1,$label);like($s->{stderr},$pattern,"$label diagnostic");$s->{stderr}=''; }
sql(q{SET statement_timeout='10s'; SET client_min_messages=warning; CREATE ROLE dolt_role; CREATE TABLE t(id int PRIMARY KEY,v text) USING dolt_prolly_table; INSERT INTO t VALUES(1,'base'); CREATE TABLE dependency_source(id int) USING dolt_prolly_table; INSERT INTO dependency_source VALUES(7); CREATE FUNCTION saved_function(dependency_source) RETURNS int LANGUAGE sql AS $$SELECT ($1).id$$; SELECT dolt_commit('-Am','base'); SELECT dolt_checkout('-b','other')});
sql(q{ALTER TABLE t ADD COLUMN extra text DEFAULT 'added'; UPDATE t SET v='other'});
is(sql(q{SELECT count(*) FROM dolt_query_diff('SELECT extra FROM t', $$SELECT 'added'::text AS extra$$)}),'0','query diff sees branch-local schema');
sql(q{SELECT dolt_checkout('t')});
is(sql(q{SELECT * FROM t}),'1|base','table checkout restores matching schema and rows');
is(sql(q{SELECT count(*) FROM pg_attribute WHERE attrelid='t'::regclass AND attname='extra'}),'0','restored catalog removes added column');
sql(q{ALTER TABLE t ALTER COLUMN v TYPE int USING 42; SELECT dolt_commit('-Am','changed type'); SELECT dolt_reset('--hard','HEAD~1')});
is(sql(q{SELECT v,pg_typeof(v) FROM t}),'base|text','hard reset restores prior type and contents');
sql(q{DROP TABLE t; SELECT dolt_reset('--hard')});
is(sql(q{SELECT * FROM t}),'1|base','hard reset restores dropped table and indexes');
sql(q{DROP TABLE dependency_source CASCADE; SELECT dolt_reset('--hard')});
is(sql(q{SELECT saved_function(d) FROM dependency_source d}),'7','hard reset restores dependent routines with table definitions');
fails(q{INSERT INTO t VALUES(1,'duplicate')},qr/duplicate key/,'restored index enforces uniqueness');
sql(q{UPDATE t SET v='old branch'; SELECT dolt_commit('-Am','old'); SELECT dolt_checkout('main'); SELECT dolt_branch('-D','other'); SELECT dolt_checkout('-b','other')});
is(sql(q{SELECT * FROM t}),'1|base','recreated branch overwrites old working root');
is(sql(q{SELECT count(*) FROM dolt_status}),'0','recreated branch starts clean');
my $peer=$node->background_psql('postgres',on_error_stop=>0);
$peer->query_safe(q{SET statement_timeout='2s'; SELECT dolt_checkout('other')});
sql(q{SELECT dolt_checkout('main')});
fails(q{SELECT dolt_branch('-D','other')},qr/in use by another session/,'branch deletion protects connected sessions');
sql(q{SELECT dolt_branch('-D','-f','other')});
my($out,$failed)=$peer->query(q{INSERT INTO t VALUES(2,'bad')});is($failed,1,'deleted branch rejects subsequent writes');$peer->{stderr}='';$peer->quit;
sql(q{SELECT dolt_checkout('-b','other')});
is(sql(q{SELECT * FROM t}),'1|base','forced deletion followed by recreation starts from HEAD');
fails(q{CREATE TABLE dolt_history_t(x int)},qr/reserved/,'reserved table prefix');
fails(q{CREATE SCHEMA dolt_custom},qr/reserved/,'reserved namespace prefix');
fails(q{CREATE FOREIGN TABLE dolt_foreign(x int) SERVER absent},qr/reserved/,'foreign tables cannot evade reserved names');
fails(q{CREATE TYPE dolt_composite AS (x int)},qr/reserved/,'composite relation names are reserved');
fails(q{CREATE SCHEMA AUTHORIZATION dolt_role},qr/reserved/,'implicit namespace name is reserved');
fails(q{ALTER TABLE t RENAME TO dolt_custom},qr/reserved/,'rename cannot evade reserved names');
sql(q{INSERT INTO dolt.docs VALUES('README.md','main docs'); INSERT INTO dolt.tests(test_name,test_group,test_query,assertion_type,assertion_comparator,assertion_value) VALUES('branch-test',NULL,'SELECT count(*) FROM t','expected_single_value','==','1'); INSERT INTO dolt.query_catalog VALUES('q',1,'table','SELECT * FROM t','saved')});
is(sql(q{SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_am a ON a.oid=c.relam WHERE n.nspname='public' AND c.relname IN ('dolt_docs','dolt_tests','dolt_query_catalog') AND a.amname='dolt_prolly_table'}),'3','user metadata has ordinary prolly storage');
sql(q{SELECT dolt_commit('-Am','metadata'); SELECT dolt_checkout('-b','metadata')});
sql(q{UPDATE dolt.docs SET doc_text='branch docs' WHERE doc_name='README.md'; UPDATE dolt.tests SET test_query='SELECT 2',assertion_value='2'; UPDATE dolt.query_catalog SET description='branch query'});
is(sql(q{SELECT doc_text FROM dolt.docs WHERE doc_name='README.md'}),'branch docs','branch-local documents');
is(sql(q{SELECT status FROM dolt_test_run('branch-test')}),'PASS','runner reads branch-local tests and query context');
is(sql(q{SELECT description FROM dolt.query_catalog}),'branch query','branch-local saved queries');
is(sql(q{SELECT doc_text FROM public.dolt_docs AS OF 'HEAD' WHERE doc_name='README.md'}),'main docs','document history is retained');
sql(q{SELECT dolt_checkout('other')});
is(sql(q{SELECT doc_text FROM dolt.docs WHERE doc_name='README.md'}),'main docs','other branch documents unchanged');
is(sql(q{SELECT test_query FROM dolt.tests}),'SELECT count(*) FROM t','other branch tests unchanged');
is(sql(q{SELECT description FROM dolt.query_catalog}),'saved','other branch saved queries unchanged');
sql(q{BEGIN; UPDATE dolt.docs SET doc_text='rollback' WHERE doc_name='README.md'; ROLLBACK});
is(sql(q{SELECT doc_text FROM dolt.docs WHERE doc_name='README.md'}),'main docs','ordinary metadata transaction rollback');
$s->quit;$node->restart;
is($node->safe_psql('postgres',q{SELECT dolt_checkout('metadata'); SELECT doc_text FROM dolt.docs WHERE doc_name='README.md'}),"(0,\"Switched to branch 'metadata'\")\nbranch docs",'working metadata survives restart');
$node->stop;done_testing();
